(function() {
    'use strict';

    class BalancedScorecardAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'Balanced Scorecard Strategy Execution';
            this.version = '1.1.0';
            this.EVENTS = [
                { en: 'Account manager resignations: 12 top performers in Mexico received competing offers. Retention costs impact budget.', es: 'Renuncia de gerentes de cuenta: 12 ejecutivos clave en Mexico recibieron ofertas de la competencia. Costos de retencion impactan el presupuesto.', fx: { financial: -2, customer: -1, process: 0, lg: -3 } },
                { en: 'Pfizer threatens direct distribution unless order accuracy reaches 97% within two quarters.', es: 'Pfizer amenaza con distribucion directa si la precision de pedidos no llega al 97% en dos trimestres.', fx: { financial: -1, customer: -3, process: -2, lg: 0 } },
                { en: 'Unexpected truck fleet lease due: $1.2M emergency capex required from transformation budget.', es: 'Vencimiento inesperado de leasing de flota: se requieren $1.2M de emergencia del presupuesto de transformacion.', fx: { financial: -4, customer: 0, process: -1, lg: 0 } },
                { en: 'Competitor Farmanorte announces technology partnership with MedConnect Digital. Urgency to accelerate digital roadmap.', es: 'El competidor Farmanorte anuncia alianza tecnologica con MedConnect Digital. Urgencia por acelerar la hoja de ruta digital.', fx: { financial: 0, customer: -2, process: -1, lg: -1 } },
                { en: 'Competitor data breach creates opportunity to acquire 3 key accounts if digital capabilities are in place.', es: 'Una brecha de datos del competidor crea oportunidad de adquirir 3 cuentas clave si las capacidades digitales estan listas.', fx: { financial: 2, customer: 3, process: 0, lg: 0 } },
                { en: 'New cold-chain regulations announced for biologics. Compliance deadline in 4 quarters.', es: 'Nuevas regulaciones de cadena de frio anunciadas para biologicos. Plazo de cumplimiento en 4 trimestres.', fx: { financial: -1, customer: 0, process: -3, lg: -1 } },
                { en: 'Cruz Verde Chile (11% of revenue) demands 99.5% on-time delivery within two quarters or will switch to competitor.', es: 'Cruz Verde Chile (11% de ingresos) exige 99.5% de entrega a tiempo en dos trimestres o cambiara de proveedor.', fx: { financial: -2, customer: -4, process: -1, lg: 0 } },
                { en: 'Peso devaluation in Mexico and Colombia: fuel costs +18%, debt service costs increase. EBITDA pressure.', es: 'Devaluacion del peso en Mexico y Colombia: costos de combustible +18%, aumento de servicio de deuda. Presion sobre EBITDA.', fx: { financial: -5, customer: 0, process: -1, lg: 0 } }
            ];
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0 || !state.history || state.history.length === 0) {
                state.domainState = {
                    financialScore: 45,
                    customerScore: 40,
                    processScore: 35,
                    lgScore: 25,
                    compositeHistory: [],
                    financialHistory: [],
                    customerHistory: [],
                    processHistory: [],
                    lgHistory: [],
                    prevFinImprove: 0,
                    prevCustImprove: 0,
                    prevProcImprove: 0,
                    prevLgImprove: 0,
                    ebitdaMargin: 7.8,
                    nps: 12,
                    retention: 88,
                    eventIndex: 0,
                    lastEventText: ''
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    financialPct: 25,
                    customerPct: 25,
                    processPct: 25,
                    lgPct: 25,
                    initiative: 'balanced'
                };
            }
            this._setupSliderListeners();
            this._updateEventPanel(state.domainState.lastEventText);
        }

        _setupSliderListeners() {
            var self = this;
            var ids = ['financialInput', 'customerInput', 'processInput', 'lgInput'];
            var valIds = ['financialValue', 'customerValue', 'processValue', 'lgValue'];
            ids.forEach(function(id, i) {
                var el = document.getElementById(id);
                if (el) {
                    el.addEventListener('input', function() {
                        var valEl = document.getElementById(valIds[i]);
                        if (valEl) valEl.textContent = el.value + '%';
                        self._updateTotalStatus();
                    });
                }
            });
            this._updateTotalStatus();
        }

        _updateTotalStatus() {
            var ids = ['financialInput', 'customerInput', 'processInput', 'lgInput'];
            var total = 0;
            ids.forEach(function(sid) {
                var s = document.getElementById(sid);
                if (s) total += parseInt(s.value);
            });
            var ok = (total === 100);
            var totalEl = document.getElementById('totalAllocation');
            if (totalEl) {
                totalEl.textContent = total + '%';
                totalEl.style.color = ok ? '#1e7e34' : '#c0392b';
            }
            var statusEl = document.getElementById('allocStatus');
            if (statusEl) {
                var tf = (window.mySimulation && window.mySimulation.t) ? window.mySimulation.t.bind(window.mySimulation) : function(k){ return k; };
                statusEl.textContent = ok ? tf('alloc_ok') : tf('alloc_adjust');
                statusEl.className = 'bsc-sim-alloc-status ' + (ok ? 'is-ok' : 'is-bad');
            }
        }

        _updateEventPanel(text) {
            var panel = document.getElementById('eventPanel');
            var textEl = document.getElementById('eventText');
            if (panel && textEl) {
                if (text && text.length > 0) {
                    panel.style.display = 'block';
                    textEl.innerHTML = text;
                } else {
                    panel.style.display = 'none';
                }
            }
        }

        validateDecisions(decisions) {
            var finEl = document.getElementById('financialInput');
            var custEl = document.getElementById('customerInput');
            var procEl = document.getElementById('processInput');
            var lgEl = document.getElementById('lgInput');
            var initEl = document.getElementById('initiativeSelect');

            if (finEl) decisions.financialPct = parseInt(finEl.value);
            if (custEl) decisions.customerPct = parseInt(custEl.value);
            if (procEl) decisions.processPct = parseInt(procEl.value);
            if (lgEl) decisions.lgPct = parseInt(lgEl.value);
            if (initEl) decisions.initiative = initEl.value;

            var total = decisions.financialPct + decisions.customerPct + decisions.processPct + decisions.lgPct;

            if (total !== 100) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('total_warning'), 'warning'
                );
                return false;
            }

            if (decisions.lgPct < 15) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('lg_min_warning'), 'warning'
                );
                return false;
            }

            if (decisions.financialPct > 40 || decisions.customerPct > 40 || decisions.processPct > 40 || decisions.lgPct > 40) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('max_warning'), 'warning'
                );
                return false;
            }

            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;

            var lgBase = (d.lgPct - 20) * 0.35;
            var procBase = (d.processPct - 20) * 0.35 + ds.prevLgImprove * 0.4;
            var custBase = (d.customerPct - 20) * 0.35 + ds.prevProcImprove * 0.4;
            var finBase = (d.financialPct - 20) * 0.35 + ds.prevCustImprove * 0.4;

            var initBonus = { financial: 0, customer: 0, process: 0, lg: 0 };
            if (d.initiative === 'capability') { initBonus.lg = 3; initBonus.financial = -1; }
            else if (d.initiative === 'process') { initBonus.process = 3; initBonus.lg = -1; }
            else if (d.initiative === 'customer') { initBonus.customer = 3; initBonus.process = -1; }
            else if (d.initiative === 'financial') { initBonus.financial = 3; initBonus.customer = -1; }
            else { initBonus.financial = 1; initBonus.customer = 1; initBonus.process = 1; initBonus.lg = 1; }

            var evtIdx = ds.eventIndex % this.EVENTS.length;
            var evt = this.EVENTS[evtIdx];
            var lang = (window.mySimulation && (window.mySimulation.currentLanguage === 'es' || window.mySimulation.language === 'es')) ? 'es' : 'en';
            ds.lastEventText = evt[lang];
            ds.eventIndex = evtIdx + 1;

            var lgChange = lgBase + initBonus.lg + evt.fx.lg;
            var procChange = procBase + initBonus.process + evt.fx.process;
            var custChange = custBase + initBonus.customer + evt.fx.customer;
            var finChange = finBase + initBonus.financial + evt.fx.financial;

            ds.lgScore = Math.min(100, Math.max(0, ds.lgScore + lgChange));
            ds.processScore = Math.min(100, Math.max(0, ds.processScore + procChange));
            ds.customerScore = Math.min(100, Math.max(0, ds.customerScore + custChange));
            ds.financialScore = Math.min(100, Math.max(0, ds.financialScore + finChange));

            ds.prevLgImprove = lgChange;
            ds.prevProcImprove = procChange;
            ds.prevCustImprove = custChange;
            ds.prevFinImprove = finChange;

            var composite = (ds.financialScore + ds.customerScore + ds.processScore + ds.lgScore) / 4;

            ds.ebitdaMargin = Math.min(15, Math.max(3, 7.8 + (ds.financialScore - 45) * 0.12));
            ds.nps = Math.round(12 + (ds.customerScore - 40) * 0.7);
            ds.retention = Math.min(99, Math.max(70, 88 + (ds.customerScore - 40) * 0.18));

            ds.compositeHistory.push(Math.round(composite * 10) / 10);
            ds.financialHistory.push(Math.round(ds.financialScore * 10) / 10);
            ds.customerHistory.push(Math.round(ds.customerScore * 10) / 10);
            ds.processHistory.push(Math.round(ds.processScore * 10) / 10);
            ds.lgHistory.push(Math.round(ds.lgScore * 10) / 10);

            var self = this;
            setTimeout(function() {
                self._updateEventPanel(ds.lastEventText);
            }, 500);

            return {
                period: state.currentPeriod,
                financialScore: Math.round(ds.financialScore * 10) / 10,
                customerScore: Math.round(ds.customerScore * 10) / 10,
                processScore: Math.round(ds.processScore * 10) / 10,
                lgScore: Math.round(ds.lgScore * 10) / 10,
                composite: Math.round(composite * 10) / 10,
                ebitdaMargin: Math.round(ds.ebitdaMargin * 10) / 10,
                nps: ds.nps,
                retention: Math.round(ds.retention * 10) / 10,
                budgetUsed: 4.5
            };
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('financialDisplay', 'domainState.financialScore', function(v) { return Math.round(v); });
            uiManager.bind('customerDisplay', 'domainState.customerScore', function(v) { return Math.round(v); });
            uiManager.bind('processDisplay', 'domainState.processScore', function(v) { return Math.round(v); });
            uiManager.bind('lgDisplay', 'domainState.lgScore', function(v) { return Math.round(v); });
            uiManager.bind('ebitdaDisplay', 'domainState.ebitdaMargin', function(v) { return v.toFixed(1) + '%'; });
            uiManager.bind('npsDisplay', 'domainState.nps', function(v) { return (v >= 0 ? '+' : '') + v; });
            uiManager.bind('retentionDisplay', 'domainState.retention', function(v) { return v.toFixed(1) + '%'; });
            uiManager.bind('compositeDisplay', 'results.composite', function(v) { return v ? v.toFixed(1) : '36.3'; });
        }

        getChartConfig() {
            return {
                compositeChart: {
                    type: 'line',
                    data: {
                        labels: [],
                        datasets: [{
                            label: 'BSC Composite Score',
                            data: [],
                            borderColor: '#1a3a5c',
                            backgroundColor: 'rgba(26,58,92,0.1)',
                            borderWidth: 3,
                            fill: true,
                            tension: 0.3
                        }]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            title: { display: true, text: 'BSC Composite Score Over Time' }
                        },
                        scales: {
                            y: { beginAtZero: false, min: 0, max: 100 }
                        }
                    }
                },
                perspectiveChart: {
                    type: 'line',
                    data: {
                        labels: [],
                        datasets: [
                            {
                                label: 'Financial',
                                data: [],
                                borderColor: '#27ae60',
                                backgroundColor: 'rgba(39,174,96,0.05)',
                                borderWidth: 2,
                                tension: 0.3
                            },
                            {
                                label: 'Customer',
                                data: [],
                                borderColor: '#2980b9',
                                backgroundColor: 'rgba(41,128,185,0.05)',
                                borderWidth: 2,
                                tension: 0.3
                            },
                            {
                                label: 'Process',
                                data: [],
                                borderColor: '#e67e22',
                                backgroundColor: 'rgba(230,126,34,0.05)',
                                borderWidth: 2,
                                tension: 0.3
                            },
                            {
                                label: 'Learning & Growth',
                                data: [],
                                borderColor: '#8e44ad',
                                backgroundColor: 'rgba(142,68,173,0.05)',
                                borderWidth: 2,
                                tension: 0.3
                            }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            title: { display: true, text: 'Perspective Scores Over Time' }
                        },
                        scales: {
                            y: { beginAtZero: false, min: 0, max: 100 }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            var labels = state.domainState.compositeHistory.map(function(_, i) { return 'Q' + (i + 1); });
            return {
                compositeChart: {
                    labels: labels,
                    datasets: [{ data: state.domainState.compositeHistory }]
                },
                perspectiveChart: {
                    labels: labels,
                    datasets: [
                        { data: state.domainState.financialHistory },
                        { data: state.domainState.customerHistory },
                        { data: state.domainState.processHistory },
                        { data: state.domainState.lgHistory }
                    ]
                }
            };
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            var last = history[history.length - 1];
            var composites = history.map(function(r) { return r.results ? r.results.composite : 0; });
            var finalComposite = composites[composites.length - 1] || 0;
            var avgComposite = composites.reduce(function(s, v) { return s + v; }, 0) / composites.length;

            var t = (window.mySimulation && window.mySimulation.t) ? function(k){ return window.mySimulation.t(k); } : function(k){ return k; };
            var performance = t('perf_needs');
            if (finalComposite >= 47 && avgComposite >= 42) performance = t('perf_good');
            if (finalComposite >= 53 && avgComposite >= 45) performance = t('perf_excellent');
            if (finalComposite >= 58 && avgComposite >= 47) performance = t('perf_outstanding');

            var insights = [];
            if (last && last.results) {
                if (last.results.lgScore > 70) insights.push(t('insight_lg_strong'));
                if (last.results.financialScore > 70) insights.push(t('insight_fin_strong'));
                if (last.results.customerScore < 50) insights.push(t('insight_cust_weak'));
                if (last.results.processScore < 50) insights.push(t('insight_proc_weak'));
            }
            if (insights.length === 0) insights.push(t('insight_default'));

            return {
                finalComposite: finalComposite,
                avgComposite: Math.round(avgComposite * 10) / 10,
                ebitdaMargin: last && last.results ? last.results.ebitdaMargin : 7.8,
                nps: last && last.results ? last.results.nps : 12,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            if (results.composite < 35) return window.mySimulation.t('hint_critical');
            if (results.lgScore < 30) return window.mySimulation.t('hint_lg_low');
            if (results.financialScore < 35 && state.currentPeriod <= 4) return window.mySimulation.t('hint_patience');
            if (results.composite > 65) return window.mySimulation.t('hint_good');
            return null;
        }

        getHistoryTableConfig() {
            return [
                { key: 'results.financialScore', label: 'Financial', i18nKey: 'col_financial', formatter: function(v) { return v.toFixed(1); } },
                { key: 'results.customerScore', label: 'Customer', i18nKey: 'col_customer', formatter: function(v) { return v.toFixed(1); } },
                { key: 'results.processScore', label: 'Process', i18nKey: 'col_process', formatter: function(v) { return v.toFixed(1); } },
                { key: 'results.lgScore', label: 'L&G', i18nKey: 'col_lg', formatter: function(v) { return v.toFixed(1); } },
                { key: 'results.composite', label: 'BSC Composite', i18nKey: 'col_composite', formatter: function(v) { return v.toFixed(1); } },
                { key: 'results.ebitdaMargin', label: 'EBITDA %', i18nKey: 'col_ebitda', formatter: function(v) { return v.toFixed(1) + '%'; } }
            ];
        }

        getPresets() { return null; }

        getTranslations() {
            return {
                en: {
                    title:              `Balanced Scorecard Strategy Execution`,
                    subtitle:           `Helix Pharma Distribution S.A. — Executive Turnaround`,
                    period_label:       `Quarter`,
                    period_of:          `of`,
                    financial_label:    `Financial`,
                    customer_label:     `Customer`,
                    process_label:      `Internal Process`,
                    lg_label:           `Learning & Growth`,
                    ebitda_label:       `EBITDA Margin`,
                    nps_label:          `NPS`,
                    retention_label:    `Retention`,
                    composite_label:    `BSC Composite`,
                    event_heading:      `Quarter Event`,
                    decisions_heading:  `Budget Allocation by Perspective`,
                    allocation_hint:    `Allocate your quarterly transformation budget across the four BSC perspectives. Minimum 15% for Learning & Growth; maximum 40% for any perspective. Total must equal 100%.`,
                    financial_alloc_label: `Financial (%)`,
                    customer_alloc_label:  `Customer (%)`,
                    process_alloc_label:   `Internal Process (%)`,
                    lg_alloc_label:        `Learning & Growth (%)`,
                    total_label:        `Total Allocation:`,
                    initiative_label:   `Strategic Focus`,
                    init_balanced:      `Balanced Approach`,
                    init_capability:    `Capability Building`,
                    init_process:       `Process Optimization`,
                    init_customer:      `Customer Excellence`,
                    init_financial:     `Financial Discipline`,
                    submit_btn:         `Submit Quarter`,
                    undo_btn:           `Undo Last Quarter`,
                    total_warning:      `Budget allocation must total exactly 100%.`,
